<?php require_once __DIR__ . '/../includes/auth.php'; require_login(); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename=parts.csv'); echo "SKU,Tên,Dan mục,Tồn kho,Tồn tối thiểu,Đơn giá,Nhà cung cấp\n"; $rows=db()->query('SELECT sku,name,category,stock,min_stock,price,supplier FROM parts ORDER BY name')->fetchAll(); foreach($rows as $r){echo '"'.implode('\",\"',array_map(static fn($v)=>str_replace('"','""',(string)$v),$r)).'"'."\n";} exit;
